function lev(a,b){ var m=a.length, n=b.length; var d=[];
  for(var i=0;i<=m;i++){ d[i]=new Array(n+1); d[i][0]=i; }
  for(var j=0;j<=n;j++) d[0][j]=j;
  for(var i=1;i<=m;i++) for(var j=1;j<=n;j++){ var cost=(a[i-1]===b[j-1])?0:1;
    d[i][j]=Math.min(d[i-1][j]+1, d[i][j-1]+1, d[i-1][j-1]+cost); }
  return d[m][n]; }
var EXPORTS={lev:lev};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.EditDistanceForgePure = EXPORTS; }
